def next_permutation(perm):
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    result = list(perm)
                    result[i], result[j] = result[j], result[i]
                    result[i + 1:] = reversed(result[i + 1:])
                    return result


